  // 配對規則（大班 5–6 歲；後面新增也要過這關，寧少勿濫）：
  // 1. 圖要讓孩子先說出「這一個詞」，不是親戚詞。
  // 2. 卡片上一定印大大的繁體中文詞。
  // 3. 狐狸一定唸詞：「Ｘ的第一個音是誰？」
  // 4. 注音是該印出來的詞的聲符，不是諧音或再聯想。
  // 5. 兩種唸法都合理就刪或換（冰塊/濕、白杯子/可樂、鉛筆/字、雪花/雪、餃子/包子）。
  //    可樂只能配「一看就是可樂」的棕色汽水＋吸管或瓶裝；沒有這種圖就不要用 ㄎ/可樂（口袋圖也要真的是口袋）。ㄎ現用恐龍。
  // 6. 國字看圖認字：圖＋印的字就是那個字（山/水/火/人），不能再轉一層（大象≠大）。
