  function makeOrderQuestions(onlyRoutine) {
    var want = arguments.length ? onlyRoutine : state.dayMode ? state.dayOrderRoutine : "";
    var routines = orderRoutineList();
    if (want === "wash" || want === "out" || want === "brush") {
      var i;
      for (i = 0; i < routines.length; i++) {
        if (routines[i].routine === want) return [cloneOrderRoutine(routines[i])];
      }
    }
    return rotateNoRepeat(routines, 4);
  }

  function makeBodyQuestions() {
    var singles = [
      { ask: "摸摸手", steps: ["hand"] },
      { ask: "點點頭", steps: ["head"] },
      { ask: "找找腳", steps: ["foot"] },
      { ask: "肚子在哪？", steps: ["belly"] },
      { ask: "摸摸頭", steps: ["head"] },
    ];
    var doubles = [
      { ask: "先摸頭，再摸腳", steps: ["head", "foot"] },
      { ask: "先摸手，再摸肚子", steps: ["hand", "belly"] },
      { ask: "先點頭，再摸手", steps: ["head", "hand"] },
    ];
    return shuffle(singles).concat(shuffle(doubles)).slice(0, 8);
  }

