  function topTools(extraLeft) {
    return (
      '<div class="topbar">' +
      (extraLeft || '<span></span>') +
      '<div class="home-tools">' +
      '<button class="icon-btn" type="button" data-action="sound" aria-label="' +
      (state.soundOn ? "關閉聲音" : "打開聲音") +
      '">' +
      (state.soundOn ? "🔊" : "🔇") +
      "</button>" +
      '<button class="icon-btn" type="button" data-action="fullscreen" aria-label="全螢幕">⛶</button>' +
      "</div></div>"
    );
  }

  function renderLevelCards(list) {
    return list
      .map(function (lv) {
        return (
          '<button class="level-card ' +
          lv.cls +
          '" type="button" data-action="start" data-level="' +
          lv.id +
          '">' +
          levelPreview(lv.id) +
          '<span class="name">' +
          lv.name +
          "</span>" +
          (lv.id === "next" || lv.id === "missing" || lv.id === "ord"
            ? '<span class="hint">' + escapeHtml(lv.hint) + "</span>"
            : "") +
          "</button>"
        );
      })
      .join("");
  }

  function renderMiniIcons(list, cls) {
    if (!list || !list.length) return "";
    return list
      .slice(0, 4)
      .map(function (it) {
        return '<i class="' + cls + '">' + (it.emoji || "") + "</i>";
      })
      .join("");
  }

  function renderDayBanner(world) {
    var done = todayDoneCount(world);
    var plan = todayPlanOf(world);
    var evening = dayIsFinished(world);
    var at = markerSpot(world);
    var homeBits =
      renderMiniIcons(world.outfit, "bit") || '<i class="bit">🛏️</i>';
    var parkBits =
      renderMiniIcons(world.residentAnimals, "bit") || '<i class="bit">🌳</i>';
    return (
      '<button class="day-banner' +
      (evening ? " is-evening" : "") +
      (world.lastWeather ? " wx-" + world.lastWeather : "") +
      '" type="button" data-action="open-day" aria-label="小狐狸的一天">' +
      '<div class="day-banner-scene at-' +
      at +
      '" aria-hidden="true">' +
      '<span class="mini-corner mini-home"><i class="mini-hut"></i>' +
      homeBits +
      "</span>" +
      '<span class="mini-corner mini-road"><i class="mini-crosswalk"></i><i class="bit">🚦</i></span>' +
      '<span class="mini-corner mini-park"><i class="bit">🌳</i>' +
      parkBits +
      "</span>" +
      renderFoxWear(world, "mini") +
      "</div>" +
      '<div class="day-banner-copy">' +
      "<strong>小狐狸的一天</strong>" +
      '<span class="day-banner-progress">今天 ' +
      done +
      " / " +
      plan.length +
      "</span>" +
      '<span class="day-banner-bits">' +
      renderMiniIcons(world.outfit, "bit") +
      renderMiniIcons(world.tableItems, "bit") +
      renderMiniIcons(world.residentAnimals, "bit") +
      "</span></div>" +
      '<span class="day-banner-go">' +
      escapeHtml(dayCtaLabel(world)) +
      "</span></button>"
    );
  }

  function wareKindOf(item) {
    var key = (item && item.key) || "";
    if (key === "bowl" || key === "cup" || key === "plate" || key === "sticks" || key === "spoon" || key === "fork") {
      return key;
    }
    var blob = (
      ((item && (item.name || "")) + " " + (item && (item.emoji || "")) + " " + (item && (item.id || "")))
    ).toLowerCase();
    if (/杯|🥛|cup/.test(blob)) return "cup";
    if (/盤|🍽️|plate/.test(blob)) return "plate";
    if (/筷|🥢/.test(blob)) return "sticks";
    if (/匙|🥄|spoon/.test(blob)) return "spoon";
    if (/叉|🍴|fork/.test(blob)) return "fork";
    if (/書|📖|book/.test(blob)) return "book";
    if (/球|⚽|ball/.test(blob)) return "ball";
    if (/鞋|👟|shoe/.test(blob)) return "shoe";
    if (/碗|🍚|bowl/.test(blob)) return "bowl";
    return "bowl";
  }

  function renderDayTableBits(world) {
    var items = world.tableItems || [];
    var bits = "";
    if (items.length) {
      var vessels = [];
      var seen = {};
      var i;
      for (i = 0; i < items.length && vessels.length < 3; i++) {
        var kind = wareKindOf(items[i]);
        if (kind !== "bowl" && kind !== "cup" && kind !== "plate") {
          if (!seen.bowl) {
            seen.bowl = 1;
            vessels.push("bowl");
          }
          continue;
        }
        if (seen[kind]) continue;
        seen[kind] = 1;
        vessels.push(kind);
      }
      if (!vessels.length) vessels.push("bowl");
      bits =
        '<span class="day-table-set">' +
        '<span class="day-table-bits">' +
        vessels
          .map(function (kind) {
            return '<i class="day-utensil ware-' + kind + '"></i>';
          })
          .join("") +
        "</span></span>";
    }
    return (
      '<span class="day-table-art">' +
      '<i class="dtb-top"></i><i class="dtb-leg a"></i><i class="dtb-leg b"></i>' +
      bits +
      "</span>"
    );
  }

  function renderThemeScrap(mark, i) {
    var rot = ((i * 7) % 11) - 5;
    var style = ' style="--r:' + rot + 'deg"';
    if (mark.kind === "glyph" && mark.glyph) {
      return '<i class="theme-scrap scrap-glyph"' + style + ">" + escapeHtml(mark.glyph) + "</i>";
    }
    if (mark.kind === "pic") {
      var pic = mark.emoji || escapeHtml(mark.word || mark.glyph || "");
      return '<i class="theme-scrap scrap-pic"' + style + ">" + pic + "</i>";
    }
    if (mark.kind === "count" && mark.n) {
      return (
        '<i class="theme-scrap scrap-count"' +
        style +
        ">" +
        (mark.emoji || "") +
        "<b>" +
        mark.n +
        "</b></i>"
      );
    }
    return "";
  }

  function renderThemeWall(world) {
    var marks = ((world && world.themeWall) || []).slice();
    var starOn = state.starsTotal > 0 && marks.length > 0;
    var room = starOn ? THEME_WALL_SHOW - 1 : THEME_WALL_SHOW;
    var show = marks.slice(Math.max(0, marks.length - room));
    if (!show.length) {
      return '<div class="theme-wall is-empty" aria-hidden="true"><i class="theme-hook"></i></div>';
    }
    var html = '<div class="theme-wall" aria-hidden="true">';
    var i;
    for (i = 0; i < show.length; i++) {
      html += renderThemeScrap(show[i], i);
    }
    if (starOn) {
      html += '<i class="theme-scrap scrap-star" style="--r:2deg">⭐' + state.starsTotal + "</i>";
    }
    html += "</div>";
    return html;
  }

  function namedCritterKind(it) {
    var blob = ((it && it.name) || "") + ((it && it.emoji) || "");
    if (/鴨|🦆/.test(blob)) return "duck";
    if (/貓頭鷹|🦉/.test(blob)) return "owl";
    if (/羊|🐑/.test(blob)) return "sheep";
    if (/蟹|🦀/.test(blob)) return "crab";
    if (/駱駝|🐪/.test(blob)) return "camel";
    if (/兔|🐰/.test(blob)) return "rabbit";
    if (/蜥蜴|🦎/.test(blob)) return "lizard";
    if (/魚|🐟|🐠/.test(blob)) return "fish";
    if (/鳥|🐦/.test(blob)) return "bird";
    return "";
  }

  function dayCritterKind(it) {
    var named = namedCritterKind(it);
    if (named) return named;
    if (it && it.zone === "water") return "fish";
    if (it && it.zone === "tree") return "bird";
    if (it && it.zone === "desert") return "camel";
    return "rabbit";
  }

  function isHabitatAnimalItem(item) {
    return !!(item && namedCritterKind(item) && item.name !== "車子" && item.name !== "點心" && !item.feed);
  }

  function habitatMarkItem(item, zone) {
    return {
      name: (item && item.name) || "",
      emoji: (item && item.emoji) || "",
      zone: zone || (item && (item.zone || item.slot)) || "grass",
    };
  }

  function shouldDrawHabitatCritter(item) {
    if (!isHabitatAnimalItem(item)) return false;
    if (state.levelId === "habitat") return true;
    if (state.levelId === "dress" || state.levelId === "table" || state.levelId === "sort") return false;
    return true;
  }

  function renderDayCritterMark(it, i, seat, extraInner) {
    var zone = it.zone || "grass";
    var kind = dayCritterKind(it);
    var motion = zone === "water" ? "swim" : zone === "tree" ? "perch" : "bob";
    var inner = "";
    if (kind === "bird" || kind === "owl") inner += '<i class="day-critter-feet"></i>';
    if (kind === "bird") inner += '<i class="day-critter-tail"></i>';
    if (kind === "rabbit" || kind === "bird") inner += '<i class="day-critter-eye"></i>';
    if (extraInner) inner += extraInner;
    return (
      '<i class="day-critter in-' +
      zone +
      " kind-" +
      kind +
      " " +
      motion +
      '" style="--bob-i:' +
      i +
      ";--seat:" +
      seat +
      '" aria-label="' +
      escapeHtml(it.name) +
      '">' +
      inner +
      "</i>"
    );
  }

